export const notificationViewPage = {
  id: 'notification-view',
  slug: 'notification-view'
}

sections: {
    consignment: '1. About the consignment',
    arrival: '2. Arrival and destination',
    parties: '3. Consignment parties'
  },

typeLabels: {
    potatoes: 'Potatoes (seed or ware)',
    'plants-for-planting': 'Plants for planting',
    'wood-and-cut-trees': 'Wood and cut trees'
  },

actions.items[0].href = detailsHref(
        { params: { journeyId }, query: { change: '1' } },
        { index }
      )

statusLabels: {
    'already-arrived': 'Yes, it has already arrived',
    'not-yet-arrived': 'No, it has not arrived yet'
  }

if (!scope.has(ARRIVAL_STATUS)) {
    return POTATO_ARRIVAL
  }
  return answers[ARRIVAL_STATUS] === ALREADY_ARRIVED
    ? ALREADY_ARRIVED
    : NOT_YET_ARRIVED

errors: {
    parties: {
      consignor: 'Select an address for the consignor',
      placeOfDestination: 'Select an address for the place of destination'
    }
  },

if (Object.keys(errors).length > 0) {
    return (await render(request, h, current, false)).code(
      HTTP_STATUS_BAD_REQUEST
    )
  }

if (!current.scope.readyForCheckYourAnswers) {
    return h.redirect(hubPath(current.journey.journeyId))
  }

submit: {
    heading: 'Now submit your notification',
    body: 'Continue to the declaration to submit your notification.'
  },

if (current.journey.status === state.SUBMITTED) {
    return h.redirect(pagePath(current.journey.journeyId, page.slug))
  }

export const declarationPage = {
  id: 'declaration',
  slug: 'declaration'
}

...(journey.status === state.DRAFT && {
          lateNotificationIndicator: lateness(
            requestClock(request),
            answers.commodityType,
            answers.arrivalDate
          )
        })

if (!result.ok) {
    return h.redirect(pagePath(journey.journeyId, kit.CYA_SLUG))
  }

if (journey.status === state.SUBMITTED) {
    return h.redirect(pagePath(journey.journeyId, 'confirmation'))
  }

if (journey.status !== state.SUBMITTED) {
    return h.redirect(pagePath(journey.journeyId, kit.CYA_SLUG))
  }

await expect(
    page.getByRole('link', { name: sharedCopy.layout.back, exact: true })
  ).toHaveCount(0)

if (!isRealDate(Number(year), Number(month), Number(day))) {
    return 'on-time'
  }

export const lateNotificationIndicator = {
  id: 'c9e1043b-7fba-42d2-80c2-6d6384d9630c',
  name: 'lateNotificationIndicator',
  status: 'optional',
  system: true
}

export const evaluationBindings = feature('review', [
  scalar({
    field: 'lateNotificationIndicator',
    obligation: lateNotificationIndicator
  })
])
